text:
Отвечай только валидным JSON без пояснений и без markdown. Схема:
{"[поле1]": "строка", "[поле2]": число, "[поле3]": ["список строк"]}
Если данных нет — ставь null.

curl https://api.openai.com/v1/chat/completions \
  -H "Authorization: Bearer $OPENAI_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "model": "[название модели]",
    "messages": [
      {"role": "system", "content": "Ты полезный помощник."},
      {"role": "user", "content": "Привет!"}
    ]
  }'

curl "https://generativelanguage.googleapis.com/v1beta/models/[название модели]:generateContent" \
  -H "x-goog-api-key: $GEMINI_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "contents": [{"parts": [{"text": "Привет!"}]}]
  }'

curl http://localhost:11434/api/chat -d '{
  "model": "[модель]",
  "messages": [{"role": "user", "content": "Привет!"}],
  "stream": false
}'

const resp = await fetch("[адрес API]", {
  method: "POST",
  headers: {
    "Authorization": `Bearer ${process.env.API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: "[модель]",
    messages: [{ role: "user", content: "Привет!" }],
  }),
});
const data = await resp.json();
console.log(data);
